2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Runs after {@link EnsureHouseholdUnique} has allowed the request: when the new owner shares a
15	 * household with one or more existing owners (same lastName and address, compared the same way as
16	 * {@link EnsureHouseholdUnique}), it assigns them all the same {@code householdId} — a stable
17	 * identifier derived deterministically from the normalized lastName and address, so every member of
18	 * the household resolves to the same value regardless of creation order. Existing members that
19	 * predate the household are back-filled so both sides carry the shared id. An owner with no household
20	 * peer keeps a null {@code householdId}. It also records {@code householdSize} — the number of owners
21	 * that share the household after this create (the existing peers plus this new owner) — which drives
22	 * the GOLD membership tier.
23	 */
24	public class AssignHouseholdId {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String lastName = normalize(owner.getLastName());
28	        String address = OwnerAddress.normalize(owner.getAddress());
29	        List<Owner> household = new ArrayList<>();
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (lastName.equals(normalize(existing.getLastName()))
32	                    && address.equals(OwnerAddress.normalize(existing.getAddress()))) {
33	                household.add(existing);
34	            }
35	        }
36	        // Record the household size after this create: the existing peers plus this new owner.
37	        owner.setHouseholdSize(household.size() + 1);
38	        if (household.isEmpty()) {
39	            return; // no peer at this lastName + address, so no shared household
40	        }
41	        String householdId = deriveHouseholdId(lastName, address);
42	        owner.setHouseholdId(householdId);
43	        for (Owner existing : household) {
44	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
45	                existing.setHouseholdId(householdId);
46	                ownerRepository.save(existing);
47	            }
48	        }
49	    }
50	
51	    /** {@code H-} plus the first 12 upper-case hex chars of SHA-256(lastName + '|' + address). */
52	    private static String deriveHouseholdId(String lastName, String address) {
53	        try {
54	            byte[] digest = MessageDigest.getInstance("SHA-256")
55	                    .digest((lastName + '|' + address).getBytes(StandardCharsets.UTF_8));
56	            StringBuilder sb = new StringBuilder("H-");
57	            for (int i = 0; i < 6; i++) {
58	                sb.append(String.format("%02X", digest[i]));
59	            }
60	            return sb.toString();
61	        }
62	        catch (NoSuchAlgorithmException ex) {
63	            throw new IllegalStateException("SHA-256 not available", ex);
64	        }
65	    }
66	
67	    /** Lower-cased, trimmed, with runs of whitespace collapsed to a single space. */
68	    private static String normalize(String value) {
69	        if (value == null) {
70	            return "";
71	        }
72	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
73	    }
74	}
